-- Phase 6C: service credits and controlled refunds
create table if not exists service_credits(id uuid primary key default gen_random_uuid(), credit_id varchar(50) not null unique, customer_id uuid not null references users(id) on delete restrict, order_id varchar(60), amount numeric(12,2) not null check(amount>0), reason text not null, status varchar(20) not null default 'ISSUED', issued_by uuid references users(id) on delete set null, created_at timestamptz not null default now());
create index if not exists ix_service_credits_customer on service_credits(customer_id,created_at desc);
create table if not exists refund_requests(id uuid primary key default gen_random_uuid(), refund_id varchar(50) not null unique, order_id varchar(60) not null, payment_id varchar(60), amount numeric(12,2) not null check(amount>0), reason text not null, status varchar(20) not null default 'PENDING', remarks text, requested_by uuid references users(id) on delete set null, processed_by uuid references users(id) on delete set null, processed_at timestamptz, created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create index if not exists ix_refund_requests_order on refund_requests(order_id,created_at desc);
